// DTunnel (painel novo de 03/11/2026): login + sincronizar a conta, cookies guardados num "pote".
const H = this.helpers; const B = 'https://painel.dtunnel.com.br';
const seg = n => { const i = $('S').all().find(x => x.json.chave === n); return i ? String(i.json.valor || '') : ''; };
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36';
const pote = {};
const guarda = r => { let sc = r.headers['set-cookie'] || []; if (!Array.isArray(sc)) sc = [sc]; for (const c of sc) { const kv = String(c).split(';')[0]; const k = kv.split('=')[0].trim(); const v = kv.slice(k.length + 1); if (v) pote[k] = v; else delete pote[k]; } };
const ck = () => Object.entries(pote).map(([k, v]) => k + '=' + v).join('; ');
const acao = async (pag, id, corpo) => { const r = await H.httpRequest({ method: 'POST', url: B + pag, body: corpo, json: false, timeout: 60000, returnFullResponse: true, ignoreHttpStatusErrors: true, disableFollowRedirect: true,
  headers: { 'Accept': 'text/x-component', 'Next-Action': id, 'Origin': B, 'Referer': B + pag, 'User-Agent': UA, 'Content-Type': 'text/plain;charset=UTF-8', Cookie: ck() } });
  guarda(r); const corpoTxt = String(r.body || ''); const l1 = corpoTxt.split('\n').filter(x => /^1:/.test(x)).join('');
  let res = null; try { res = JSON.parse(l1.slice(2)); } catch (e) {} return { status: r.statusCode, res, bruto: l1.slice(0, 200) }; };
const pagina = async (pag) => String(await H.httpRequest({ method: 'GET', url: B + pag, json: false, timeout: 60000, headers: { 'User-Agent': UA, Cookie: ck(), 'RSC': '1' } }));
// lista JSON que comeca em "pos" (respeita aspas)
const lerLista = (t, pos) => { let d = 0, s = false, esc = false; for (let j = pos; j < t.length; j++) { const c = t[j]; if (s) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === '"') s = false; continue; } if (c === '"') s = true; else if (c === '[' || c === '{') d++; else if (c === ']' || c === '}') { d--; if (d === 0) return t.slice(pos, j + 1); } } return ''; };
const hoje = d => new Date(Date.now() + d * 86400000).toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo' }).slice(0, 10);
const senha = seg('dtunnel_senha');
if (!senha) return [{ json: { ok: false, erro: 'falta a senha do DTunnel na tabela segredos (dtunnel_senha)' } }];
const lg = await acao('/login', '405b519d2d62441fd421a3e0fd61901d6b0edfc4f6', JSON.stringify([{ email: seg('dtunnel_usuario') || seg('dtunnel_email'), password: senha }]));
if (!(lg.res && lg.res.success)) return [{ json: { ok: false, erro: 'login no DTunnel recusado (' + ((lg.res && lg.res.error) || lg.status) + ')' + ((lg.res && lg.res.requiresMfa) ? ' - o DTunnel pediu código de verificação (MFA)' : '') } }];
await acao('/home', '0090c780e5b57c8943f884dd3dca83042eb3eba103', '[]'); // sincroniza a conta (sem isso o painel novo da erro 500)

const pn = await pagina('/notificacao'); const k = pn.indexOf('{"items":['); let itens = [];
if (k > -1) { try { itens = JSON.parse(lerLista(pn, k + 9)); } catch (e) {} }
const pg = await pagina('/aplicativo'); let perfil = null; let p = pg.indexOf('[{"id":');
while (p > -1 && !perfil) { const txt = lerLista(pg, p); try { const arr = JSON.parse(txt); const c = arr.find(x => x && x.fields && (x.source === 'default' || x.isActive)); if (c) perfil = c; } catch (e) {} p = pg.indexOf('[{"id":', p + 1); }
const imgs = perfil ? perfil.fields.filter(f => /netliss-devocional|\.png|\.jpg/i.test(String(f.value))).map(f => f.name + '=' + f.value) : [];
return [{ json: { hoje: hoje(0), notas: itens.slice(0, 6).map(x => ({ id: String(x.id).slice(0, 8), t: x.title, s: x.status, at: x.scheduledAt })), perfil: perfil ? { id: perfil.id, userId: perfil.userId ? 'sim' : 'nao', source: perfil.source, isActive: perfil.isActive, nCampos: perfil.fields.length } : null, imgs } }];
